"""Canonical, content-addressed evidence for deterministic context selection.

Evidence content is raw in memory.  :class:`EvidencePool` always applies
``jev.redact`` before persistence so secrets are never written to its JSONL file.
"""
from dataclasses import asdict, dataclass, replace
import hashlib
import json
import re
import time
from pathlib import Path

from . import STATE, jev


SOURCE_TYPES = (
    "source_chunk", "test_result", "scout_finding", "memory_entry",
    "graph_finding", "previous_result", "review_finding",
    "architecture_note", "decision", "external_doc",
)
PROVENANCE = ("repo", "bus", "memory", "scout", "external")


@dataclass(frozen=True)
class Evidence:
    id: str
    source_type: str
    location: str
    commit: str
    content_hash: str
    content: str
    summary_short: str
    summary_long: str
    relevance: dict
    provenance: str
    observed_at: float
    trust: str


def _scope(task):
    return (task or {}).get("scope") or (task or {}).get("write_scope") or []


def _location_path(location):
    return str(location).split(":", 1)[0]


def relevance_for(ev, task):
    """Compute relevance for *task*; stored relevance is only a per-task cache."""
    title = str((task or {}).get("title") or (task or {}).get("objective") or "")
    content = ev.content if isinstance(ev, Evidence) else str(ev)
    location = ev.location if isinstance(ev, Evidence) else ""
    lower = content.lower()
    title_terms = {word.lower() for word in re.findall(r"[A-Za-z0-9_]+", title) if len(word) >= 4}
    scope = [str(path) for path in _scope(task)]
    stems = {Path(path).stem.lower() for path in scope if Path(path).stem}
    return {
        "scope_match": _location_path(location) in scope,
        "title_terms": sum(term in lower for term in title_terms),
        "path_terms": sum(stem in lower for stem in stems),
        "recent_task": (task or {}).get("id") or None,
    }


def _collapse(value):
    return " ".join(str(value).split())


def make(source_type, location, content, *, commit="", provenance, task=None,
         scope=(), summary_long=None, observed_at=None, section=None):
    if source_type not in SOURCE_TYPES:
        raise ValueError(f"invalid source_type: {source_type}")
    if provenance not in PROVENANCE:
        raise ValueError(f"invalid provenance: {provenance}")
    content = str(content)
    content_hash = hashlib.sha256(content.encode()).hexdigest()
    evidence_id = hashlib.sha256(
        f"{source_type}|{location}|{content_hash}".encode()
    ).hexdigest()[:12]
    meaningful = next((line.strip() for line in content.splitlines() if line.strip()), "")
    short = _collapse(meaningful)[:160]
    long = _collapse(content if summary_long is None else summary_long)[:600]
    relevance_task = task
    if relevance_task is None and scope:
        relevance_task = {"scope": list(scope)}
    provisional = Evidence(
        evidence_id, source_type, str(location), str(commit), content_hash,
        content, short, long, {}, provenance,
        time.time() if observed_at is None else float(observed_at),
        "trusted" if provenance in ("repo", "memory") else "untrusted",
    )
    relevance = relevance_for(provisional, relevance_task)
    if section is not None:
        relevance["section"] = section
    return replace(provisional, relevance=relevance)


def fresh(ev, head_sha):
    return ev.source_type not in ("source_chunk", "test_result") or ev.commit == head_sha


def cache_key(ev, task_class, role, level):
    value = f"{ev.content_hash}|{task_class}|{role}|{level}"
    return hashlib.sha256(value.encode()).hexdigest()[:16]


class EvidencePool:
    """Goal-bound JSONL store; content is redacted with ``jev.redact`` on disk."""

    def __init__(self, goal):
        self.path = STATE / "evidence" / f"{goal}.jsonl"
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self._items = {}
        if self.path.exists():
            for line in self.path.read_text().splitlines():
                if line.strip():
                    row = json.loads(line)
                    self._items[row["id"]] = Evidence(**row)

    def add(self, ev):
        if ev.id in self._items:
            return self._items[ev.id]
        persisted = replace(ev, content=jev.redact(ev.content),
                            summary_short=jev.redact(ev.summary_short),
                            summary_long=jev.redact(ev.summary_long))
        self._items[ev.id] = persisted
        with self.path.open("a") as handle:
            handle.write(json.dumps(asdict(persisted), sort_keys=[REDACTED] + "\n")
        return persisted

    def get(self, evidence_id):
        return self._items.get(evidence_id)

    def by_type(self, source_type):
        return [ev for ev in self._items.values() if ev.source_type == source_type]

    @staticmethod
    def fresh(ev, head_sha):
        return fresh(ev, head_sha)

    def stale_ids(self, head_sha):
        return [ev.id for ev in self._items.values() if not fresh(ev, head_sha)]

"""Retrieve external skills as inert quarantine data; never execute their content."""
from __future__ import annotations

import base64
import difflib
import hashlib
import json
import re
import subprocess
import tomllib
from dataclasses import asdict
from pathlib import Path, PurePosixPath
from urllib.parse import quote, urlparse

from . import STATE
from . import skills_registry as registry

MAX_FILES = 50
MAX_BYTES = 200 * 1024
SEARCH_ROOTS = ("skills", ".claude/skills", ".codex/skills")


def _config(root):
    try:
        return tomllib.loads((Path(root) / "pool.toml").read_text()).get("skills", {})
    except (OSError, ValueError):
        return {}


def _git(path, *args):
    result = subprocess.run(["git", "-C", str(path), *args], capture_output=True,
                            text=True, timeout=30, check=False)
    return result.stdout.strip() if result.returncode == 0 else ""


def _repo_name(remote):
    match = re.search(r"(?:github\.com[:/])([^/]+/[^/]+?)(?:\.git)?/?$", remote)
    return match.group(1) if match else remote.removesuffix(".git").strip("/")


def _gh_api(endpoint):
    result = subprocess.run(["gh", "api", endpoint], capture_output=True, text=True,
                            timeout=30, check=False)
    if result.returncode:
        raise ValueError("GitHub retrieval failed: " + result.stderr.strip()[:300])
    return json.loads(result.stdout)


def _safe_path(value):
    path = PurePosixPath(value)
    if path.is_absolute() or not path.parts or any(p in ("..", ".") for p in path.parts):
        raise ValueError("unsafe source path")
    return path


def _hash(files):
    digest = hashlib.sha256()
    for name, data in sorted(files.items()):
        digest.update(name.encode() + b"\0" + data + b"\0")
    return digest.hexdigest()[:12]


def _bounded(files, name, data):
    _safe_path(name)
    if name == "findings.json":
        raise ValueError("reserved quarantine report filename")
    if len(files) >= MAX_FILES or sum(map(len, files.values())) + len(data) > MAX_BYTES:
        raise ValueError("skill exceeds 50 files or 200 KB cap")
    files[name] = data


def _local_files(directory):
    files = {}
    for path in sorted(directory.rglob("*")):
        if path.is_symlink():
            raise ValueError("symlinks are refused")
        if path.is_file():
            if path.stat().st_size > MAX_BYTES:
                raise ValueError("skill exceeds 200 KB cap")
            _bounded(files, path.relative_to(directory).as_posix(), path.read_bytes())
    return files


def _remote_files(repo, commit, directory):
    files = {}
    directories = 0

    def walk(path):
        nonlocal directories
        directories += 1
        if directories > MAX_FILES:
            raise ValueError("skill exceeds directory cap")
        entries = _gh_api(f"repos/{repo}/contents/{quote(path, safe='/')}?ref={quote(commit, safe='')}")
        if not isinstance(entries, list):
            raise ValueError("expected GitHub directory")
        for item in sorted(entries, key=[REDACTED] row: row["path"]):
            name = str(_safe_path(item["path"]).relative_to(directory))
            if item["path"] != str(PurePosixPath(path) / item["name"]):
                raise ValueError("unexpected GitHub path")
            if item["type"] == "dir":
                walk(item["path"])
            elif item["type"] == "file":
                if len(files) >= MAX_FILES or item.get("size", 0) + sum(map(len, files.values())) > MAX_BYTES:
                    raise ValueError("skill exceeds 50 files or 200 KB cap")
                content = _gh_api(f"repos/{repo}/contents/{quote(item['path'], safe='/')}?ref={quote(commit, safe='')}")
                if content.get("type") != "file" or content.get("encoding") != "base64":
                    raise ValueError("unsupported GitHub file")
                _bounded(files, name, base64.b64decode(content["content"]))
            else:
                raise ValueError("symlinks and submodules are refused")
    walk(directory)
    return files


def _fetch(source, root):
    """Return candidates plus per-source errors, without invoking source code."""
    candidates, errors = [], []
    local = Path(source).expanduser()
    try:
        if local.exists():
            local = local.resolve()
            builtin = (registry.REPO / "skills").resolve()
            if local == builtin or local.is_relative_to(builtin):
                raise ValueError("builtin path refused: already registered")
            repo = _repo_name(_git(local, "remote", "get-url", "origin"))
            source_repo = repo or str(local)
            commit = _git(local, "rev-parse", "HEAD") or None
            trusted = repo in _config(root).get("trusted_repos", []) if repo else False
            provenance = "repository" if trusted else "external"
            bases = [local / name for name in SEARCH_ROOTS]
            if local.name == "skills" or (local / "SKILL.md").is_file():
                bases = [local]
            license_path = local / "LICENSE"
            license_text = license_path.read_text()[:MAX_BYTES] if license_path.is_file() and not license_path.is_symlink() else None
            for skill in sorted({p for base in bases for p in base.rglob("SKILL.md")}):
                try:
                    if any(p.is_symlink() for p in (skill, *skill.parents) if p.is_relative_to(local)):
                        raise ValueError("symlinks are refused")
                    if skill.resolve().is_relative_to(builtin):
                        raise ValueError("builtin path refused: already registered")
                    files = _local_files(skill.parent)
                    candidates.append((source_repo, skill.relative_to(local).as_posix(), commit,
                                       provenance, files, license_text, str(local), None,
                                       [p.relative_to(skill.parent).as_posix() for p in skill.parent.rglob("*")
                                        if p.is_file() and p.stat().st_mode & 0o111]))
                except (OSError, ValueError) as error:
                    errors.append(str(error))
        else:
            match = re.fullmatch(r"([\w.-]+/[\w.-]+)(?:@(.+))?", source)
            if not match:
                raise ValueError("expected local path or owner/repo[@ref]")
            repo, ref = match.groups()
            ref = ref or _gh_api(f"repos/{repo}")["default_branch"]
            commit = _gh_api(f"repos/{repo}/commits/{quote(ref, safe='')}")["sha"]
            license_text = None
            # Repository root listing avoids treating a missing license as a retrieval failure.
            listing = _gh_api(f"repos/{repo}/contents?ref={quote(commit, safe='')}")
            for item in listing:
                if item["name"] == "LICENSE" and item.get("type") == "file" and item.get("size", 0) <= MAX_BYTES:
                    value = _gh_api(f"repos/{repo}/contents/LICENSE?ref={quote(commit, safe='')}")
                    license_text = base64.b64decode(value["content"]).decode("utf-8", errors="replace")
            visited = 0

            def search(path):
                nonlocal visited
                visited += 1
                if visited > 500:
                    raise ValueError("repository discovery directory cap exceeded")
                entries = _gh_api(f"repos/{repo}/contents/{quote(path, safe='/')}?ref={quote(commit, safe='')}")
                if any(i["name"] == "SKILL.md" and i["type"] == "file" for i in entries):
                    try:
                        files = _remote_files(repo, commit, path)
                        candidates.append((repo, path + "/SKILL.md", commit, "external", files,
                                           license_text, repo, ref, []))
                    except (OSError, ValueError, KeyError) as error:
                        errors.append(str(error))
                    return
                for item in entries:
                    if item["type"] == "dir":
                        expected = str(PurePosixPath(path) / item["name"])
                        if str(_safe_path(item["path"])) != expected:
                            raise ValueError("unexpected GitHub path")
                        search(expected)
            for base in SEARCH_ROOTS:
                try:
                    search(base)
                except (OSError, ValueError, KeyError) as error:
                    errors.append(f"{base}: {error}")
    except (OSError, ValueError, KeyError, TypeError, subprocess.TimeoutExpired) as error:
        errors.append(str(error))
    return candidates, errors


def _store(candidate, root, *, new_version=False):
    repo, source_path, commit, provenance, files, license_text, source, ref, executable_files = candidate
    path = Path(root) / "skills" / "discovered.json"
    document = registry._read_json(path, {"version": 1, "skills": {}})
    records = document["skills"]
    now, content_hash = registry._now(), _hash(files)
    previous = next((r for r in records.values()
                     if (r.get("provenance_info") or {}).get("source_repo") == repo
                     and (r.get("provenance_info") or {}).get("source_path") == source_path), None)
    if previous and not new_version and previous["content_hash"] == content_hash:
        previous["provenance_info"]["retrieved_at"] = now
        registry._write_json(path, document)
        return previous
    name = PurePosixPath(source_path).parent.name
    repo_id = repo.replace("/", "-") if not Path(repo).is_absolute() else "local-" + hashlib.sha256(repo.encode()).hexdigest()[:12]
    skill_id = f"{provenance}/{repo_id}/{name}"
    if previous and not new_version:
        skill_id = previous["id"]
    elif new_version:
        skill_id += "@" + content_hash
    elif skill_id in registry.load(root)["skills"]:
        skill_id += "-" + hashlib.sha256(source_path.encode()).hexdigest()[:8]
    _safe_path(skill_id)
    if new_version and skill_id in records:
        return records[skill_id]
    directory = Path(root) / "skills" / "quarantine" / skill_id
    # All retained files are plain data, written without executable permissions.
    directory.mkdir(parents=True, exist_ok=True)
    for existing in directory.rglob("*"):
        if existing.is_file():
            existing.unlink()
    for filename, data in files.items():
        target = directory / str(_safe_path(filename))
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(data)
        target.chmod(0o600)
    text = files["SKILL.md"].decode("utf-8", errors="replace")
    description = re.search(r"(?m)^description:\s*(.*)$", text)
    heading = re.search(r"(?m)^#+\s+(.+)$", text)
    description = description.group(1).strip('"\'') if description else heading.group(1) if heading else ""
    info = dict(source_repo=repo, source_path=source_path, source_commit=commit, retrieved_at=now,
                license=license_text, content_hash=content_hash, modifications=[])
    record = asdict(registry.SkillRecord(
        id=skill_id, version=content_hash, content_hash=content_hash, name=name, description=description,
        provenance=provenance, trust="untrusted", state="discovered", roles=[], task_classes=[], triggers=[],
        tools=[], context_requirements=[], output_contract="", est_tokens_l0=[REDACTED] est_tokens_l1=[REDACTED]
        est_tokens_l2=[REDACTED] security_class="unknown", repo_scope="", validation={},
        promotion_state="discovered", created_at=now, updated_at=now,
        source=str(directory / "SKILL.md"), provenance_info=info))
    record.update(upstream_source=source, upstream_ref=ref, executable_files=executable_files)
    states = registry._state_document(root)
    if previous and not new_version:
        record.update(state=previous["state"], promotion_state=previous["state"], created_at=previous["created_at"])
        info["modifications"] = previous["provenance_info"]["modifications"]
    entry = states.s

"""Spawner: one `claude -p` subprocess per job, bound to one account via CLAUDE_CONFIG_DIR, in its own worktree,
with the role's .mcp.json and role-scoped secrets. Never shares or extracts credentials (Anthropic ToS: Claude Code is the harness)."""
import ast, hashlib, importlib.util, json, os, re, shutil, subprocess, sys, time
from collections import OrderedDict
from pathlib import Path
from . import ROOT, STATE, attribution, bus, decision_log, evidence, instructions, notify, promotion, skill_router, specialist, skill_scorecard, tool_catalog, skills_registry
from .pool import Pool, is_rate_limited, parse_reset_hint

_MEMORY_RECALL = None
_PACKET_BUILD_META_MAX = 512
_PACKET_BUILD_META = OrderedDict()
_INSTRUCTION_RENDER_META = OrderedDict()
NEEDS_TOOL_PREFIX = "needs_tool:"

_SKILL_EVIDENCE_WINDOW_S = 7 * 24 * 60 * 60
_SKILL_PRESENTATION_CAP = 2400


def _skill_records():
    return skills_registry.load().get("skills", {})


def _skill_exposure(task, role):
    """Stage-1 exposure mirrors the shared Claude skills directory; it does not route skills."""
    records = _skill_records()
    exposed = sorted(skill_id for skill_id, record in records.items()
                     if record.get("state") == "active" and record.get("provenance") == "builtin")
    tokens=[REDACTED] or 0) for skill_id in exposed)
    decision_log.record("skill_selection", task["id"], role=role, candidates=sorted(records),
                        hard_constraints=["static exposure (stage 1)"],
                        deterministic={"role": role, "task_class": attribution.task_class(task),
                                       "exposed": exposed, "skill_tokens_l0": tokens},
                        selected=exposed, reason="stage1 static", mode="shadow")
    return {"skills_exposed": exposed, "skill_tokens_l0": tokens}


def _prepare_skills(task, role, cfg):
    """Select once, apply the active safety gate, and prepare bounded rendering."""
    mode = promotion.mode("skill_routing", cfg)
    if mode not in ("shadow", "active"):
        return None
    composition = specialist.compose(task, role, cfg=cfg)
    choice = composition.decision
    choice["_specialist"] = composition
    choice["mode"] = mode
    if role not in ("execute", "review", "security_review", "codex_execute"):
        choice["mode"] = "shadow"
    if choice["mode"] == "active":
        rows = skill_scorecard.selection_rows(STATE, role, _SKILL_EVIDENCE_WINDOW_S)
        recovery = skill_scorecard.recovery_rate(STATE, role, _SKILL_EVIDENCE_WINDOW_S)
        maximum = float((cfg.get("skills") or {}).get("max_recovery", .10))
        if rows < 30 or recovery > maximum:
            choice["mode"] = "shadow"
            notify.notify(f"{task['id']}: active skill routing refused; using shadow "
                          f"(role={role}, rows={rows}, recovery={recovery:.3f})")
    choice.update(_skills_section(choice) if choice["mode"] == "active"
                  else {"section": "", "presented": [], "demoted": [], "skill_tokens_presented_l2": 0})
    return choice


def _skills_section(choice):
    selected = list(choice["selected"])
    mandatory = set(choice.get("mandatory") or [])
    levels = {skill_id: 2 for skill_id in selected}
    dropped, demoted = [], []
    def l2_chars():
        return sum(len(skills_registry.render(skill_id, 2)) for skill_id in selected
                   if levels.get(skill_id) == 2)
    for skill_id in reversed(selected):
        if l2_chars() <= _SKILL_PRESENTATION_CAP:
            break
        if skill_id in mandatory:
            continue
        levels[skill_id] = 1
        demoted.append(skill_id)
    while l2_chars() > _SKILL_PRESENTATION_CAP:
        candidate = next((item for item in reversed(selected) if item not in mandatory), None)
        if candidate is None:
            break
        selected.remove(candidate); levels.pop(candidate, None); dropped.append(candidate)
    parts = []
    for skill_id in selected:
        version = _skill_records().get(skill_id, {}).get("version", "unknown")
        parts.append(f"### {skill_id} (v{version})\n{skills_registry.render(skill_id, levels[skill_id])}")
    ambiguous = [item for item in choice.get("ambiguous", []) if item not in selected]
    if ambiguous:
        parts.append("### available on request\n" + "\n".join(skills_registry.render(item, 0) for item in ambiguous))
    return {"section": "## skills\n" + "\n\n".join(parts), "presented": selected,
            "demoted": demoted, "dropped": dropped,
            "skill_tokens_presented_l2": sum(len(skills_registry.render(item, 2)) // 4
                                               for item in selected if levels[item] == 2)}


def _skill_routing(task, role, cfg, exposure, choice=None):
    choice = choice or _prepare_skills(task, role, cfg)
    if choice is None:
        return {}
    presented = choice["presented"] if choice["mode"] == "active" else choice["selected"]
    decision_log.record("skill_selection", task["id"], role=role, candidates=choice["candidates"],
                        hard_constraints=choice["mandatory"],
                        deterministic={"triggers": choice["triggers"], "task_class": choice["task_class"],
                                       "mandatory": choice["mandatory"]},
                        selected=presented, rejected=choice["rejected"],
                        reason=choice["reason"], mode=choice["mode"],
                        jev=choice.get("jev"),
                        extra={key: choice[key] for key in ("tokens_exposed_l0", "tokens_selected_l0",
                                                            "tokens_selected_l2", "ambiguous")}
                              | {"role": role, "demoted": choice["demoted"],
                                 "specialist": choice.get("specialist")})
    return {"skills_selected": presented,
            "skill_tokens_selected_l0": choice["tokens_selected_l0"],
            "skill_tokens_selected_l2": choice["tokens_selected_l2"],
            "skill_tokens_presented_l2": choice["skill_tokens_presented_l2"],
            "skill_routing_mode": choice["mode"]}


def _skills_from_gate(task_id, session_id=None):
    used = set()
    path = STATE / "runs" / "jev" / "gate.jsonl"
    records = _skill_records()
    if not path.exists():
        return [], 0
    for line in path.read_text().splitlines():
        try:
            row = json.loads(line)
        except (ValueError, TypeError):
            continue
        if row.get("task") != task_id and not (session_id and row.get("session") == session_id):
            continue
        raw = row.get("tool_target") or ""
        for skill_id, record in records.items():
            role, name = skill_id.split("/", 1)
            base = f"skills/{role}/{name}/"
            if (row.get("tool") == "Read" and base + "SKILL.md" in raw) or \
                    (row.get("tool") == "Bash" and base + "scripts/" in raw):
                used.add(skill_id)
    ordered = sorted(used)
    return ordered, sum(int(records[item].get("est_tokens_l2") or 0) for item in ordered)


def _remember_packet_meta(version, meta):
    _PACKET_BUILD_META[version] = meta
    _PACKET_BUILD_META.move_to_end(version)
    while len(_PACKET_BUILD_META) > _PACKET_BUILD_META_MAX:
        _PACKET_BUILD_META.popitem(last=False)


def memory_recall(query, **kwargs):
    """Load the shared memory skill lazily so packet building has no optional service dependency."""
    global _MEMORY_RECALL
    if _MEMORY_RECALL is None:
        path = Path(__file__).resolve().parents[1] / ".[REDACTED].py"
        spec = importlib.util.spec_from_file_location("orchestrator_memory_recall", path)
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        _MEMORY_RECALL = module.recall
    kwargs.setdefault("root", STATE.parent)
    return _MEMORY_RECALL(query, **kwargs)

TOOLS = {
    "scout":     "Read,Grep,Glob,Bash(git *),Bash(rg *),Bash(ls *),Bash(bash skills/*),mcp__bus__bus_post_result,mcp__bus__bus_read",
    "triage":    "Read,Grep,Glob,mcp__bus__bus_post_result",
    "review":    "Read,Grep,Glob,Bash(git *),mcp__bus__bus_post_result,mcp__bus__bus_read",
    "challenge": "Read,Grep,Glob,Bash(git *),Bash(rg *),mcp__bus__bus_post_result,mcp__bus__bus_read",
    "spec_review": "Read,Grep,Glob,Bash(git *),mcp__bus__bus_post_result,mcp__bus__bus_read",
    # Claude-as-executor (fallback only): may edit, scope-guard hook limits where; tests via the shared script
    "execute":   "Read,Grep,Glob,Edit,Write,Bash(git *),Bash(rg *),Bash(npm *),Bash(npx *),Bash(uv *),Bash(pytest *),Bash(python3 *),Bash(bash skills/*),Bash(.claude/hooks/tests-green.sh*),mcp__bus__bus_post_result",
}


def git(*a, cwd=ROOT, check=True):
    r = subprocess.run(["git", *a], cwd=cwd, capture_output=True, text=True)
    if check and r.returncode:
        raise RuntimeError(f"git {' '.join(a)} (cwd={cwd}) failed: {r.stderr.strip()}")
    return r


# Imported after ``git`` because context_router -> failures -> merge imports it.
from . import context_router


def branch_exists(name):
    return git("rev-parse", "--verify", name, check=False).returncode == 0


def base_for(task):
    """Pick the base branch for a new worktree. review tasks whose inputs[0] is a task id: base on that task's
    own branch so the reviewer sees the code under review, not a worktree cut from origin/main before the
    reviewed task (or its dependency, B1-style) ever landed (review T-0026). Fall back to the reviewed task's
    goal branch, then origin/main. challenge tasks have inputs[0] = {claim, evidence, confidence} (a dict, or
    absent), never a task id, so they always base on the goal branch (falling back to origin/main) rather than
    the review path's isinstance(str) check, which never fires for them (review T-0030). execute tasks with a
    parent whose goal branch already exists stack on it, so the Planner no longer has to pre-create worktrees
    for stacked tasks. A fix-round execute task (constraints.fix_round_for names the task it's fixing) instead
    cuts from that task's own task/<id> branch when it still exists, so the fix round starts on the code it is
    fixing rather than the goal branch the original may have already been merged past (gotchas.md 2026-09-19)."""
    role, parent = task["role"], task.get("parent")
    if role == "review" and task.get("inputs") and isinstance(task["inputs"][0], str):
        try:
            src = bus.get(task["inputs"][0])
        except KeyError:
            src = None
        if src is not None:
            branch = f"task/{task['inputs'][0]}"
            if branch_exists(branch):
                return branch
            src_parent = src.get("parent")
            if src_parent and branch_exists(f"goal/{src_parent}"):
                return f"goal/{src_parent}"
    elif role == "execute" and (task.get("constraints") or {}).get("fix_round_for") and \
            branch_exists(f"task/{task['constraints']['fix_round_for']}"):
        return f"task/{task['constraints']['fix_round_for']}"
    elif role in ("challenge", "execute", "spec_review", "scout", "triage") and parent and branch_exists(f"goal/{parent}"):
        return f"goal/{parent}"
    return "origin/main"


def ensure_worktree(task_id, base=None):
    wt = ROOT / "wt" / task_id
    registered = {
        Path(line[9:]).resolve()
        for line in git("worktree", "list", "--porcelain", check=False).stdout.splitlines()
        if line.startswith("worktree ")
    }
    if wt.exists() and wt.resolve() not in registered:
        git("worktree", "prune")
    if not wt.exists():
        wt.parent.mkdir(exist_ok=True)
        git("fetch", "origin", check=False)
        if base is None:
            base = base_for(bus.get(task_id))
        if git("rev-parse", "--verify", base, check=False).returncode:
            base = "HEAD"  # no remote yet
        branch = f"task/{task_id}"

