"""Isolated shadow Planner launches and bounded, prompt-free evaluation rows."""
from __future__ import annotations

import json
import math
import os
from pathlib import Path
import sys
import threading
import time

from . import ROOT, STATE, bus, goals, jev, spawn

_ACTIONS = frozenset(("fix_round", "respec", "escalate", "noop", "synthesize_now",
                      "wait_for_more", "drop_low_confidence", "write_specs", "close", "other"))
_LOCK = threading.Lock()


def eligible(router_decision, cfg, *, sample=None):
    """Defensively re-check the caller's router draw; never draw a second sample."""
    if router_decision.mode != "shadow":
        return False, "mode_not_shadow"
    if router_decision.hold:
        return False, "held"
    if router_decision.shadow_tier is None:
        return False, "no_shadow_tier"
    if sample is not None and sample > cfg["shadow_sample_rate"]:
        return False, "sampled_out"
    return True, "eligible"


def argv(prompt, *, model, budget_usd, system_prompt_path):
    return ["claude", "-p", prompt, "--model", model, "--output-format", "json",
            "--max-budget-usd", str(budget_usd), "--mcp-config", ".mcp.planner-shadow.json",
            "--strict-mcp-config", "--disallowedTools",
            "Edit,Write,MultiEdit,NotebookEdit,Bash,Task,WebFetch,WebSearch",
            "--append-system-prompt", Path(system_prompt_path).read_text(encoding="utf-8"),
            "--dangerously-skip-permissions"]


def launch(prompt, *, model, account, budget_usd, log, root=ROOT, popen=None):
    """Launch independently of production; never resolve Planner service secrets."""
    try:
        root, log = Path(root), Path(log)
        command = argv(spawn.render("planner-shadow", packet=prompt), model=model,
                       budget_usd=budget_usd,
                       system_prompt_path=root / ".orchestrator/prompts/planner.md")
        env = os.environ.copy()
        env.update(CLAUDE_CONFIG_DIR=os.path.expanduser(account["config_dir"]),
                   ORCH_ROOT=str(root), ORCH_SHADOW="1")
        token=[REDACTED] or "")
        if token:
            env["CLAUDE_CODE_OAUTH_TOKEN"] = token
        log.parent.mkdir(parents=True, exist_ok=True)
        stderr_log = str(log) + ".stderr"
        with log.open("w", encoding="utf-8") as stdout, open(stderr_log, "w", encoding="utf-8") as stderr:
            proc = (popen if popen is not None else goals.Popen)(
                command, cwd=root, env=env, stdout=stdout, stderr=stderr,
                start_new_session=True)
        return {"pid": proc.pid, "log": str(log), "stderr_log": stderr_log, "argv": command}
    except Exception as exc:
        print(f"shadow Planner launch failed: {jev.redact(str(exc))}", file=sys.stderr)
        return None


def _number(value):
    try:
        result = float(value)
        return result if math.isfinite(result) else None
    except (ValueError, TypeError, OverflowError):
        return None


def _text(value, cap):
    return jev.redact(value)[:cap] if isinstance(value, str) else ""


def _strings(value, cap):
    return [_text(item, cap) for item in value if isinstance(item, str)][:10] if isinstance(value, list) else []


def _decision(result):
    action = result.get("proposed_action")
    tasks = result.get("tasks_proposed")
    confidence = _number(result.get("confidence"))
    return {
        "proposed_action": action if isinstance(action, str) and action in _ACTIONS else "other",
        "summary": _text(result.get("summary"), 800),
        "tasks_proposed": [{"title": _text(task.get("title"), 120),
                            "scope": _strings(task.get("scope"), 800)}
                           for task in tasks if isinstance(task, dict)][:10] if isinstance(tasks, list) else [],
        "confidence": max(0.0, min(1.0, confidence)) if confidence is not None else None,
        "needs_fable": result.get("needs_fable") is True,
        "unresolved": _strings(result.get("unresolved"), 200),
    }


def parse(log_path):
    """Read the final JSON envelope, retaining usage even on invalid result text."""
    try:
        lines = Path(log_path).read_text(encoding="utf-8", errors="replace").splitlines()
    except OSError:
        return None
    envelope = {}
    for line in reversed(lines):
        try:
            value = json.loads(line)
        except ValueError:
            continue
        envelope = value if isinstance(value, dict) else {}
        break
    usage = envelope.get("usage")
    fields = {"usage": bus.normalize_usage("claude", usage if isinstance(usage, dict) else {}),
              "total_cost_usd": _number(envelope.get("total_cost_usd")),
              "session_id": _text(envelope.get("session_id"), 200) or None,
              "is_error": bool(envelope.get("is_error"))}
    result_text = envelope.get("result")
    result = spawn.extract_json(result_text) if isinstance(result_text, str) and "{" in result_text else None
    if not isinstance(result, dict) or result.get("parse_error"):
        return {"parse_error": True, **fields}
    return {**_decision(result), **fields}


def record(*, launch_id, goal_id, decision_type, state_version, model, tier,
           started_at, parsed, latency_s, root=None):
    """Append one whitelisted result directly to the shadow ledger."""
    parsed = parsed or {"parse_error": True}
    result = {"parse_error": True} if parsed.get("parse_error") else _decision(parsed)
    result.update({key: parsed[key] for key in
                   ("usage", "total_cost_usd", "session_id", "is_error") if key in parsed})
    row = {**result, "launch_id": launch_id, "goal_id": goal_id,
           "decision_type": decision_type, "state_version": state_version,
           "model": model, "tier": tier, "started_at": started_at,
           "latency_s": latency_s, "ts": time.time()}
    path = (Path(root) if root is not None else STATE) / "runs/sched/planner_shadow.jsonl"
    path.parent.mkdir(parents=True, exist_ok=True)
    with _LOCK, path.open("a", encoding="utf-8") as stream:
        stream.write(json.dumps(row) + "\n")
    return row


def production_action(materiality):
    if materiality.get("escalated") is True:
        return "escalate"
    if materiality.get("fix_strategy_for"):
        return "fix_round"
    if materiality.get("new_tasks"):
        return "write_specs"
    return "noop"


def score(shadow_row, production_materiality):
    shadow = shadow_row.get("proposed_action", "other")
    production = production_action(production_materiality) if production_materiality is not None else None
    agreement = None
    if production is not None and not shadow_row.get("parse_error"):
        agreement = ("write_specs" if shadow == "synthesize_now" else shadow) == production
    matched = None
    if production_materiality is not None and "escalated" in production_materiality:
        matched = bool(shadow_row.get("needs_fable")) == bool(production_materiality["escalated"])
    return {"agreement": agreement, "basis": f"shadow={shadow}; production={production}",
            "needs_fable_matched": matched}


def summary(root=None):
    """Summarize valid ledger rows; unknown agreement is excluded from its rate."""
    path = (Path(root) if root is not None else STATE) / "runs/sched/planner_shadow.jsonl"
    rows = []
    try:
        with path.open(encoding="utf-8", errors="replace") as stream:
            for line in stream:
                try:
                    row = json.loads(line)
                except ValueError:
                    continue
                if isinstance(row, dict):
                    rows.append(row)
    except OSError:
        pass
    n = len(rows)
    agreements = [row["agreement"] for row in rows if type(row.get("agreement")) is bool]
    tokens=[REDACTED]
    for row in rows:
        usage = row.get("usage")
        if isinstance(usage, dict):
            tokens += _number(usage.get("total_tokens")) or 0
    return {"n": n,
            "agreement_rate": sum(agreements) / len(agreements) if agreements else None,
            "needs_fable_rate": sum(bool(row.get("needs_fable")) for row in rows) / n if n else None,
            "parse_error_rate": sum(bool(row.get("parse_error")) for row in rows) / n if n else None,
            "usd": sum(_number(row.get("total_cost_usd")) or 0 for row in rows),
            "tokens": tokens}

"""Read-only economics for executor and Planner handoffs."""
from __future__ import annotations

import json
from collections import defaultdict
from pathlib import Path

from . import STATE, attribution, planner_telemetry, scorecard


def _tasks(root):
    result = {}
    directory = Path(root) / "tasks"
    for path in sorted(directory.glob("*.json")) if directory.exists() else ():
        try:
            row = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        if isinstance(row, dict):
            result[row.get("id", path.stem)] = row
    return result


def _runs(root):
    rows = []
    directory = Path(root) / "runs"
    for path in sorted(directory.glob("*.jsonl")) if directory.exists() else ():
        try:
            lines = path.read_text(encoding="utf-8", errors="replace").splitlines()
        except OSError:
            continue
        for line in lines:
            try:
                row = json.loads(line)
            except (TypeError, ValueError):
                continue
            if isinstance(row, dict) and row.get("role") == "execute" and row.get("task"):
                rows.append(row)
    return rows


def _lineage(task, tasks):
    """Root/index equivalent to attribution.lineage, for an arbitrary state root."""
    root, index, current = task.get("id"), 0, task
    seen = {root}
    while True:
        constraints = current.get("constraints") or {}
        target = constraints.get("fix_round_for") if isinstance(constraints, dict) else None
        if not target or target in seen:
            break
        seen.add(target)
        root, index = target, index + 1
        current = tasks.get(target, {})
    return {"root": root, "round_index": index}


def _tokens(run):
    usage = run.get("usage") if isinstance(run.get("usage"), dict) else {}
    return sum(int(run.get(key, usage.get(key, 0)) or 0)
               for key in ("input_tokens", "output_tokens"))


def _usd(run):
    return float(run.get("usd", run.get("total_cost_usd", 0)) or 0)


def _reason(task):
    raw = str(task.get("hold_reason") or "")
    lowered = raw.lower()
    if lowered == "gate_red":
        return "gate_red"
    if lowered.startswith("review request_changes"):
        return "review"
    if "conflict" in lowered:
        return "conflict"
    return {"kind": "other", "hold_reason": raw}


def lineage_rows(root=STATE):
    """Return one ordered aggregate for every execute lineage with a run."""
    root = Path(root)
    tasks = _tasks(root)
    grouped = defaultdict(lambda: defaultdict(list))
    round_tasks = {}
    for run in _runs(root):
        task = tasks.get(run["task"], {"id": run["task"], "constraints": {}})
        info = _lineage(task, tasks)
        grouped[info["root"]][info["round_index"]].append(run)
        round_tasks[(info["root"], info["round_index"])] = task

    output = []
    for lineage_root, indexed in sorted(grouped.items()):
        ordered = sorted(indexed)
        executors = []
        tokens=[REDACTED]
        costs = []
        resume = fresh = reconstruction = 0
        estimated = False
        pairs = []
        for position, index in enumerate(ordered):
            runs = indexed[index]
            task = round_tasks[(lineage_root, index)]
            executor = next((r.get("executor") or r.get("tier") for r in runs
                             if r.get("executor") or r.get("tier")), None)
            executors.append(executor)
            tokens.append(sum(_tokens(run) for run in runs))
            costs.append(sum(_usd(run) for run in runs))
            if position:
                mode = next((run.get("resume_mode") for run in runs if run.get("resume_mode")), None)
                mode = mode or (task.get("pipeline") or {}).get("resume", {}).get("mode")
                if mode == "resume":
                    resume += 1
                else:
                    fresh += 1
                    presented = [((run.get("context") or {}).get("presented_tokens")) for run in runs]
                    measured = [value for value in presented if isinstance(value, (int, float))]
                    if measured:
                        reconstruction += sum(measured)
                    else:
                        reconstruction += sum(max(0, int(run.get("input_tokens") or 0) -
                                                   int(run.get("cache_read_input_tokens") or 0)) for run in runs)
                        estimated = True
                pairs.append((executors[position - 1], executor, _reason(task)))
        first = tasks.get(lineage_root, {})
        handoff = (first.get("pipeline") or {}).get("handoff")
        accepted = bool(first.get("merged_into"))
        output.append({
            "lineage": lineage_root, "task_class": attribution.task_class(first),
            "first_executor": executors[0], "executors_by_round": executors,
            "rounds": len(ordered), "resume_rounds": resume, "fresh_rounds": fresh,
            "tokens_by_round": tokens, "usd_by_round": costs,
            "first_pass": len(ordered) == 1 and accepted, "accepted": accepted,
            "accepted_tokens": sum(tokens) if accepted else 0,
            "accepted_usd": sum(costs) if accepted else 0,
            "reconstruction_tokens": reconstruction, "estimated": estimated,
            "handoff_pairs": pairs,
            "handoff": handoff if isinstance(handoff, dict) else None,
        })
    return output


def by_start(root=STATE):
    lineage = lineage_rows(root)
    grouped = defaultdict(list)
    for row in lineage:
        grouped[(row["first_executor"], row["task_class"])].append(row)
    result = {}
    for key, rows in grouped.items():
        n = len(rows)
        stamped = [row for row in rows if row.get("handoff")]
        active_share = (sum(bool(row["handoff"].get("switched")) for row in stamped) / len(stamped)
                        if stamped else 0.0)
        result[key] = {
            "n": n,
            "first_pass_rate": sum(row["first_pass"] for row in rows) / n,
            "avg_rounds": sum(row["rounds"] for row in rows) / n,
            "avg_accepted_tokens": sum(row["accepted_tokens"] for row in rows) / n,
            "avg_accepted_usd": sum(row["accepted_usd"] for row in rows) / n,
            "avg_reconstruction_tokens": sum(row["reconstruction_tokens"] for row in rows) / n,
            "active_share": active_share,
        }
    return result


def expected_route_cost(task_class, executor, root=STATE, cfg=None):
    rows = [row for row in lineage_rows(root)
            if row["task_class"] == task_class and row["first_executor"] == executor]
    minimum = ((cfg or {}).get("promotion") or {}).get("min_samples", 20)
    if len(rows) < minimum:
        return {"insufficient": True, "n": len(rows)}
    first = [row["tokens_by_round"][0] for row in rows]
    fixes = [sum(row["tokens_by_round"][1:]) for row in rows if row["rounds"] > 1]
    handed = [sum(cost for cost, ex in zip(row["tokens_by_round"][1:], row["executors_by_round"][1:])
                    if ex != executor) for row in rows]
    fix_rows = [row for row in rows if row["rounds"] > 1]
    handoff_rows = [row for row in rows if any(ex != executor for ex in row["executors_by_round"][1:])]
    first_term = sum(first) / len(first)
    fix_term = ((len(fix_rows) / len(rows)) *
                ((sum(fixes) / len(fixes) if fixes else 0) +
                 (sum(row["reconstruction_tokens"] for row in fix_rows) / len(fix_rows) if fix_rows else 0)))
    destination_term = ((len(handoff_rows) / len(rows)) *
                        (sum(handed) / len(handoff_rows) if handoff_rows else 0))
    return {"insufficient": False, "n": len(rows), "expected_route_cost": first_term + fix_term + destination_term,
            "terms": {"first_round": {"value": first_term, "n": len(first)},
                      "fix": {"value": fix_term, "n": len(fix_rows)},
                      "handoff_destination": {"value": destination_term, "n": len(handoff_rows)}}}


def recommendation(task_class, root=STATE, cfg=None):
    rows = [row for row in lineage_rows(root) if row["task_class"] == task_class]
    executors = sorted({row["first_executor"] for row in rows if row["first_executor"]})
    costs = {executor: expected_route_cost(task_class, executor, root, cfg) for executor in executors}
    sufficient = {executor: value for executor, value in costs.items() if not value.get("insufficient")}
    selected = min(sufficient, key=[REDACTED] key: sufficient[key]["expected_route_cost"]) if sufficient else None
    first_cost = {}
    for executor in executors:
        values = [row["tokens_by_round"][0] for row in rows if row["first_executor"] == executor]
        if values:
            first_cost[executor] = sum(values) / len(values)
    cheapest = min(first_cost, key=[REDACTED] if first_cost else None
    return {"task_class": task_class, "executor": selected, "cheapest_first": cheapest,
            "start_strong": selected is not None and cheapest != selected, "costs": costs}


def _shadow_rows(root):
    path = Path(root) / "runs/sched/planner_shadow.jsonl"
    rows = []
    try:
        lines = path.read_text(encoding="utf-8", errors="replace").splitlines()
    except OSError:
        return rows
    for line in lines:
        try:
            row = json.loads(line)
        except ValueError:
            continue
        if isinstance(row, dict):
            rows.append(row)
    return rows


def planner_handoffs(root=STATE):
    invocations = planner_telemetry.read_invocations(root)
    shadow_by_goal = defaultdict(list)
    for row in _shadow_rows(root):
        shadow_by_goal[row.get("goal_id")].append(row)
    accepted = scorecard.accepted_goals(Path(root))
    rows = []
    for launch in invocations:
        if launch.get("route") != "escalate":
            continue
        shadow = shadow_by_goal.get(launch.get("goal_id"), [])
        before = None
        if shadow:
            usage = shadow[-1].get("usage") or {}
            before = usage.get("total_tokens")
        after = launch.get("total_tokens")
        packet_chars = launch.get("packet_chars")
        packet_tokens=[REDACTED] / 4) if isinstance(packet_chars, (int, float)) else None
        rows.append({"launch_id": launch.get("launch_id"), "goal_id": launch.get("goal_id"),
                     "before_tokens": before if before is not None else "unmeasured",
                     "escalation_packet_tokens": packet_tokens if packet_tokens is not None else "unmeasured",
                     "escalation_packet_estimated": packet_tokens is not None,
                     "after_tokens": after if after is not None else "unmeasured",
                     "accepted": launch.get("goal_id") in accepted})
    numeric = lambda key: [row[key] for row in rows if isinstance(row[key], (int, float))]
    return {"rows": rows, "n": len(rows),
            "accepted": sum(row["accepted"] for row in rows),
            "averages": {key: (sum(values) / len(values) if values else "unmeasured")
                         for key in ("before_tokens", "escalation_packet_tokens", "after_tokens")
                         for values in [numeric(key)]}}


def build(root=STATE, cfg=None):
    starts = by_start(root)
    classes = sorted({key[1] for key in starts})
    return {"by_start": {"/".join(key): value for key, value in starts.items()},
            "recommendations": {name: recommendation(name, root, cfg) for name in classes},
            "planner_handoffs": planner_handoffs(root)}


def format_report(card):
    return json.dumps(card, indent=1)

