"""Pure, deterministic routing of canonical evidence into context levels."""
from dataclasses import dataclass
import fnmatch
import re

from . import evidence
from .failures import _test_ids as test_ids


LEVELS = ("HIDE", "SHORT", "LONG", "FULL")


@dataclass(frozen=True)
class Routed:
    evidence_id: str
    level: str
    reason: str
    tokens_full: int
    tokens_at_level: int


@dataclass(frozen=True)
class RoutedPacket:
    items: list
    candidate_tokens: int
    routed_tokens: int
    reduction_ratio: float
    ambiguous_ids: list
    profile: str
    rules_version: str = "v1"


def _path(ev):
    return ev.location.split(":", 1)[0]


def _text(ev, level):
    if level == "HIDE":
        return ""
    if level == "SHORT":
        return f"- {ev.location} — {ev.summary_short}"
    if level == "LONG":
        return f"- {ev.location}\n  {ev.summary_long}"
    fence = "`" * max(3, 1 + max((len(run) for run in re.findall(r"`+", ev.content)), default=0))
    return f"- {ev.location}\n{fence}\n{ev.content}\n{fence}"


def _security_match(path, cfg):
    review = (cfg or {}).get("review") or {}
    return any(fnmatch.fnmatch(path, pattern) for pattern in review.get("security_paths", []))


def _choice(task, ev, role, head_sha, cfg, failing_ids):
    relevance = evidence.relevance_for(ev, task)
    scope = task.get("scope") or task.get("write_scope") or []
    in_scope = _path(ev) in scope

    if ev.source_type == "source_chunk" and in_scope and role in ("execute", "scout"):
        return "FULL", "in_scope_file"
    if (role == "security_review" and ev.source_type == "source_chunk"
            and _security_match(_path(ev), cfg)):
        return "FULL", "security_path"
    if ev.source_type == "source_chunk" and in_scope and role in ("review", "security_review"):
        return ("FULL" if ev.relevance.get("section") == "diff" else "LONG"), "in_scope_file"
    if role == "planner" and ev.source_type == "source_chunk":
        return "SHORT", "read_scope"
    if ev.source_type == "test_result" and role in ("review", "security_review"):
        return "FULL", "failing_output"
    if ev.source_type == "test_result" and (
            any(test_id in ev.location for test_id in failing_ids)
            or "FAIL" in ev.content or "ERROR" in ev.content):
        return "FULL", "failing_output"
    task_id = task.get("id", "")
    if (ev.source_type == "architecture_note"
            and ev.location in (f"task:{task_id}:spec", f"task:{task_id}:acceptance")):
        return "FULL", "acceptance"
    if role == "planner" and ev.source_type in ("decision", "architecture_note"):
        return "LONG", "dependency"
    if (not relevance["scope_match"] and relevance["title_terms"] == 0
            and relevance["path_terms"] == 0
            and ev.source_type in ("memory_entry", "decision", "previous_result", "review_finding")):
        return "HIDE", "unrelated_memory"
    if (head_sha is not None and not evidence.fresh(ev, head_sha)
            and ev.source_type in ("source_chunk", "test_result")):
        return "HIDE", "stale"
    if ev.source_type == "source_chunk":
        return "SHORT", "read_scope"
    if role in ("review", "security_review") and ev.source_type in ("review_finding", "previous_result"):
        return "SHORT", "dependency"
    if ev.source_type in ("previous_result", "scout_finding", "decision", "memory_entry") \
            and (relevance["scope_match"] or relevance["title_terms"]):
        return "LONG", "dependency"
    return "LONG", "ambiguous"


def route(task, candidates, *, role, head_sha=None, cfg=None, required_types=()):
    profile = role if role in ("execute", "review", "security_review", "planner", "scout") else "execute"
    failing_ids = test_ids((task.get("resume_hint") or {}).get("failures")) or []
    items, ambiguous = [], []
    for ev in candidates:
        level, reason = _choice(task, ev, profile, head_sha, cfg, failing_ids)
        if ev.source_type in required_types and LEVELS.index(level) < LEVELS.index("LONG"):
            level, reason = "LONG", "skill_required_context"
        full_tokens=[REDACTED] "FULL")) // 4
        routed_tokens=[REDACTED] level)) // 4
        items.append(Routed(ev.id, level, reason, full_tokens, routed_tokens))
        if reason == "ambiguous":
            ambiguous.append(ev.id)
    candidate_tokens=[REDACTED] for item in items)
    routed_tokens=[REDACTED] for item in items)
    return RoutedPacket(items, candidate_tokens, routed_tokens,
                        routed_tokens / candidate_tokens if candidate_tokens else 1.0,
                        ambiguous, profile)


def _lookup(source, evidence_id):
    if hasattr(source, "get"):
        return source.get(evidence_id)
    if callable(source):
        return source(evidence_id)
    return source[evidence_id]


def render(routed_packet, evidence_pool_or_lookup):
    visible = [item for item in routed_packet.items if item.level != "HIDE"]
    visible.sort(key=[REDACTED] item: ({"FULL": 0, "LONG": 1, "SHORT": 2}[item.level],
                                  _lookup(evidence_pool_or_lookup, item.evidence_id).location))
    lines = ["## evidence (routed v1)"]
    lines.extend(_text(_lookup(evidence_pool_or_lookup, item.evidence_id), item.level)
                 for item in visible)
    lines.append(f"hidden: {sum(item.level == 'HIDE' for item in routed_packet.items)}")
    return "\n".join(lines)



def section_items(routed_packet, lookup, section):
    """Render whole items belonging to one section; file bodies stay on disk."""
    items = []
    for item in routed_packet.items:
        ev = _lookup(lookup, item.evidence_id)
        if ev.relevance.get("section") != section or item.level == "HIDE":
            continue
        if ev.source_type == "source_chunk" and item.reason == "in_scope_file":
            continue
        level = "SHORT" if section == "read_scope" else item.level
        items.append((level, _text(ev, level)))
    return items

def decision_row(task, routed_packet, *, mode):
    counts = {level: sum(item.level == level for item in routed_packet.items) for level in LEVELS}
    return {
        "kind": "context_selection",
        "subject": task["id"],
        "candidates": [f"{item.evidence_id}:{item.level}" for item in routed_packet.items],
        "hard_constraints": [item.reason for item in routed_packet.items if item.level == "FULL"],
        "deterministic": {"role": routed_packet.profile, **counts, "candidate_tokens": routed_packet.candidate_tokens,
                          "routed_tokens": routed_packet.routed_tokens,
                          "reduction_ratio": routed_packet.reduction_ratio,
                          "ambiguous": len(routed_packet.ambiguous_ids)},
        "selected": "routed v1",
        "reason": f"{routed_packet.profile} profile rules v1",
        "mode": mode,
        "extra": None,
    }

"""Mine repeated successful work and store inert learned-skill proposals."""
from __future__ import annotations

import hashlib
import json
import re
from collections import Counter, defaultdict
from datetime import datetime, timedelta, timezone
from pathlib import Path

from . import STATE, attribution, skill_scorecard
from . import skills_registry as registry


def _rows(path):
    if not path.exists():
        return
    for line in path.read_text(errors="replace").splitlines():
        try:
            value = json.loads(line)
        except (ValueError, TypeError):
            continue
        if isinstance(value, dict):
            yield value


def _tasks(root):
    result = {}
    for path in sorted((Path(root) / "tasks").glob("*.json")):
        try:
            value = json.loads(path.read_text())
        except (OSError, ValueError, TypeError):
            continue
        if isinstance(value, dict):
            result[str(value.get("id") or path.stem)] = value
    return result


def _cutoff(since_s):
    if since_s in (None, ""):
        return None
    if isinstance(since_s, (int, float)):
        return datetime.now(timezone.utc) - timedelta(seconds=float(since_s))
    match = re.fullmatch(r"(\d+)([dhms])", str(since_s).strip().lower())
    if not match:
        raise ValueError("--since must be a duration such as 30d")
    seconds = int(match.group(1)) * {"d": 86400, "h": 3600, "m": 60, "s": 1}[match.group(2)]
    return datetime.now(timezone.utc) - timedelta(seconds=seconds)


def _recent(row, cutoff):
    if cutoff is None:
        return True
    raw = row.get("ts") or row.get("at") or row.get("created_at")
    try:
        stamp = (datetime.fromtimestamp(float(raw), timezone.utc) if isinstance(raw, (int, float))
                 else datetime.fromisoformat(str(raw).replace("Z", "+00:00")))
    except (ValueError, TypeError, OverflowError):
        return True
    return stamp >= cutoff


def _normal_target(tool, target):
    text = str(target or "").strip()
    script = re.search(r"(?:^|\s)((?:[\w.-]+/)+(?:[\w.-]+\.(?:sh|py|js|ts)))\b", text)
    if script:
        return script.group(1)
    if str(tool).lower() in ("bash", "shell", "exec", "exec_command"):
        words = re.findall(r"[^\s]+", text)
        return words[0].rsplit("/", 1)[-1] if words else ""
    path = re.search(r"(?:^|\s)([\w./-]+)", text)
    value = path.group(1) if path else text
    return Path(value).stem if "." in Path(value).name else value.rstrip("/").rsplit("/", 1)[-1]


def _sentences(text):
    for value in re.split(r"(?<=[.!?])\s+|\n+", str(text or "")):
        sentence = re.sub(r"\s+", " ", value).strip(" -\t")
        if len(re.findall(r"\b\w+\b", sentence)) >= 8:
            yield sentence.casefold()


def _outcomes(root, tasks):
    result = {}
    for task_id, task in tasks.items():
        value = task.get("merged_into") or task.get("accepted")
        status = str(task.get("status") or (task.get("result") or {}).get("status") or "").lower()
        result[task_id] = bool(value or status in ("merged", "accepted"))
    for row in skill_scorecard.usage_rows(root):
        if row.get("accepted") is not None:
            result[str(row.get("task"))] = bool(row["accepted"])
            if row.get("lineage_root"):
                result[str(row["lineage_root"])] = bool(row["accepted"])
    # Learning must not depend on a task having selected a pre-existing skill.
    # Run logs predate skill telemetry and still carry useful terminal outcomes.
    for path in sorted((Path(root) / "runs").rglob("*.jsonl")):
        if path.name == "gate.jsonl":
            continue
        for row in _rows(path):
            task_id = row.get("task")
            outcome = str(row.get("outcome") or row.get("status") or "").casefold()
            if task_id and outcome in ("merged", "accepted"):
                result[str(task_id)] = True
    # Fix-round success belongs to the repaired lineage, not to whether the
    # auxiliary fix task itself was merged independently.
    for task_id, task in tasks.items():
        target = (task.get("constraints") or {}).get("fix_round_for")
        seen = set()
        while target in tasks and target not in seen:
            seen.add(target)
            parent = tasks[target]
            next_target = (parent.get("constraints") or {}).get("fix_round_for")
            if not next_target:
                break
            target = next_target
        if target in result:
            result[task_id] = result[target]
    return result


def _pattern(kind, signature, task_ids, evidence, tasks, outcomes, min_support):
    ids = sorted(set(task_ids))
    successes = sum(bool(outcomes.get(task)) for task in ids)
    support = len(ids)
    confidence = successes / support if support else 0.0
    roles = sorted({str(tasks.get(task, {}).get("role") or evidence.get(task, {}).get("role") or "unknown")
                    for task in ids})
    classes = sorted({attribution.task_class(tasks[task]) for task in ids if task in tasks})
    failures = [task for task in ids if not outcomes.get(task)]
    return {
        "source": kind, "procedure_signature": signature, "support_tasks": ids,
        "support": support, "successes": successes, "failures": failures,
        "roles": roles, "task_classes": classes, "confidence": round(confidence, 3),
        "evidence_strength": round(min(1.0, support / 10), 3),
        "evidence": [evidence.get(task, {}) for task in ids], "min_support": min_support,
    }


def patterns(root=STATE, since_s=None, min_support=3):
    """Return deterministic repeated patterns with at least 80 percent accepted outcomes."""
    root, minimum, cutoff = Path(root), int(min_support), _cutoff(since_s)
    tasks = _tasks(root)
    outcomes = _outcomes(root, tasks)
    found = []

    sequences = defaultdict(list)
    for row in _rows(root / "runs" / "jev" / "gate.jsonl"):
        if not _recent(row, cutoff) or not row.get("task") or not row.get("tool"):
            continue
        key=[REDACTED] str(row.get("role") or tasks.get(str(row["task"]), {}).get("role") or "unknown"))
        sequences[key].append((row.get("ts") or row.get("at") or len(sequences[key]),
                               f"{row['tool']}:{_normal_target(row['tool'], row.get('tool_target'))}"))
    groups, evidence = defaultdict(list), {}
    for (task, role), values in sequences.items():
        signature = " > ".join(item[1] for item in sorted(values, key=[REDACTED] item: str(item[0])))
        groups[(role, signature)].append(task)
        evidence[task] = {"role": role, "tools": [item[1] for item in sorted(values, key=[REDACTED] item: str(item[0]))]}
    for (_, signature), ids in groups.items():
        found.append(_pattern("tool_sequence", signature, ids, evidence, tasks, outcomes, minimum))

    instructions, instruction_evidence = defaultdict(set), defaultdict(dict)
    for task_id, task in tasks.items():
        if task.get("role") not in ("execute", "scout", "review", "spec_review") or not _recent(task, cutoff):
            continue
        for sentence in _sentences(task.get("spec")):
            instructions[sentence].add(task_id)
            instruction_evidence[sentence][task_id] = {"role": task.get("role"), "sentence": sentence}
    for sentence, ids in instructions.items():
        found.append(_pattern("instruction", "instruction:" + sentence, ids, instruction_evidence[sentence],
                              tasks, outcomes, minimum))

    fixes, fix_evidence = defaultdict(set), {}
    for task_id, task in tasks.items():
        constraints = task.get("constraints") or {}
        if not constraints.get("fix_round_for") or not _recent(task, cutoff):
            continue
        pipeline = task.get("pipeline") or {}
        strategy = (task.get("planner_note") or pipeline.get("planner_note") or
                    task.get("failure_kind") or pipeline.get("failure_kind") or
                    constraints.get("failure_kind") or task.get("note"))
        if not strategy:
            sentences = list(_sentences(task.get("spec")))
            strategy = sentences[0] if sentences else None
        if strategy:
            signature = "fix:" + re.sub(r"\s+", " ", str(strategy)).strip().casefold()
            fixes[signature].add(task_id)
            fix_evidence[task_id] = {"role": task.get("role"), "fix_strategy": str(strategy)}
    for signature, ids in fixes.items():
        found.append(_pattern("fix_strategy", signature, ids, fix_evidence, tasks, outcomes, minimum))

    return sorted((item for item in found
                   if item["support"] >= minimum and item["successes"] / item["support"] >= .8),
                  key=[REDACTED] item: (-item["evidence_strength"], item["procedure_signature"]))


def _slug(pattern):
    words = re.findall(r"[a-z0-9]+", pattern["procedure_signature"].lower())[:6]
    base = "-".join(words)[:48].strip("-") or "procedure"
    return base + "-" + hashlib.sha256(pattern["procedure_signature"].encode()).hexdigest()[:8]


def _store_learned(record, root=STATE):
    """Persist a learned record and seed lifecycle state before quarantine transition."""
    root = Path(root)
    path = root / "skills" / "discovered.json"
    document = registry._read_json(path, {"version": 1, "skills": {}})
    records = document.setdefault("skills", {})
    signature = record["provenance_info"]["procedure_signature"]
    previous = next((value for value in records.values()
                     if value.get("provenance") == "learned"
                     and (value.get("provenance_info") or {}).get("procedure_signature") == signature), None)
    if previous:
        record["id"] = previous["id"]
        record["created_at"] = previous["created_at"]
    records[record["id"]] = record
    states = registry._state_document(root)
    states.setdefault(record["id"], {"state": "discovered", "trust": "untrusted",
                                      "since": registry._now(), "history": [],
