    used = set()
    path = STATE / "runs" / "jev" / "gate.jsonl"
    records = _skill_records()
    if not path.exists():
        return [], 0
    for line in path.read_text().splitlines():
        try:
            row = json.loads(line)
        except (ValueError, TypeError):
