"""Canonical, content-addressed evidence for deterministic context selection.

Evidence content is raw in memory.  :class:`EvidencePool` always applies
``jev.redact`` before persistence so secrets are never written to its JSONL file.
``LOCAL_USER`` covers locally produced artifacts, including user memory and
observed worker outputs; it is not limited to user-authored memory.
"""
from dataclasses import asdict, dataclass, field, fields, replace
import hashlib
import json
import re
import time
from pathlib import Path

from . import STATE, jev, context_scanner


SOURCE_TYPES = (
    "source_chunk", "test_result", "scout_finding", "memory_entry",
    "graph_finding", "previous_result", "review_finding",
    "architecture_note", "decision", "external_doc", "worker_partial",
)
PROVENANCE = ("repo", "bus", "memory", "scout", "external", "worker_partial")


@dataclass(frozen=True)
class Evidence:
    id: str
    source_type: str
    location: str
    commit: str
    content_hash: str
    content: str
    summary_short: str
    summary_long: str
    relevance: dict
    provenance: str
    observed_at: float
    trust: str
    trust_class: str = ""
    scan: dict | None = None
    scope: list = field(default_factory=list)


def _trust_class(provenance):
    return {"repo": "TRUSTED_REPO", "memory": "LOCAL_USER",
            "worker_partial": "LOCAL_USER"}.get(provenance, "EXTERNAL")


def _scope(task):
    return (task or {}).get("scope") or (task or {}).get("write_scope") or []


def _location_path(location):
    return str(location).split(":", 1)[0]


def relevance_for(ev, task):
    """Compute relevance for *task*; stored relevance is only a per-task cache."""
    title = str((task or {}).get("title") or (task or {}).get("objective") or "")
    content = ev.content if isinstance(ev, Evidence) else str(ev)
    location = ev.location if isinstance(ev, Evidence) else ""
    lower = content.lower()
    title_terms = {word.lower() for word in re.findall(r"[A-Za-z0-9_]+", title) if len(word) >= 4}
    scope = [str(path) for path in _scope(task)]
    stems = {Path(path).stem.lower() for path in scope if Path(path).stem}
    return {
        "scope_match": _location_path(location) in scope,
        "title_terms": sum(term in lower for term in title_terms),
        "path_terms": sum(stem in lower for stem in stems),
        "recent_task": (task or {}).get("id") or None,
    }


def _collapse(value):
    return " ".join(str(value).split())


def make(source_type, location, content, *, commit="", provenance, task=None,
         scope=(), summary_long=None, observed_at=None, section=None):
    if source_type not in SOURCE_TYPES:
        raise ValueError(f"invalid source_type: {source_type}")
    if provenance not in PROVENANCE:
        raise ValueError(f"invalid provenance: {provenance}")
    content = str(content)
    content_hash = hashlib.sha256(content.encode()).hexdigest()
    evidence_id = hashlib.sha256(
        f"{source_type}|{location}|{content_hash}".encode()
    ).hexdigest()[:12]
    meaningful = next((line.strip() for line in content.splitlines() if line.strip()), "")
    short = _collapse(meaningful)[:160]
    long = _collapse(content if summary_long is None else summary_long)[:600]
    relevance_task = task
    if relevance_task is None and scope:
        relevance_task = {"scope": list(scope)}
    result = context_scanner.scan(content, source_kind="evidence")
    trust_class = "UNTRUSTED" if result["verdict"] == "blocked" else _trust_class(provenance)
    scan_summary = dict(verdict=result["verdict"],
                        patterns=sorted({f["pattern"] for f in result["findings"]}))
    provisional = Evidence(
        evidence_id, source_type, str(location), str(commit), content_hash,
        content, short, long, {}, provenance,
        time.time() if observed_at is None else float(observed_at),
        "trusted" if provenance in ("repo", "memory") else "untrusted",
        trust_class, scan_summary, list(scope),
    )
    relevance = relevance_for(provisional, relevance_task)
    if section is not None:
        relevance["section"] = section
    return replace(provisional, relevance=relevance)


def fresh(ev, head_sha):
    return ev.source_type not in ("source_chunk", "test_result", "worker_partial") or ev.commit == head_sha


def cache_key(ev, task_class, role, level):
    value = f"{ev.content_hash}|{task_class}|{role}|{level}"
    return hashlib.sha256(value.encode()).hexdigest()[:16]


class EvidencePool:
    """Goal-bound JSONL store; content is redacted with ``jev.redact`` on disk."""

    def __init__(self, goal):
        self.path = STATE / "evidence" / f"{goal}.jsonl"
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self._items = {}
        if self.path.exists():
            for line in self.path.read_text().splitlines():
                if line.strip():
                    row = json.loads(line)
                    row.setdefault("trust_class", _trust_class(row.get("provenance")))
                    row.setdefault("scan", None)
                    row.setdefault("scope", [])
                    row = {key: value for key, value in row.items()
                           if key in {field.name for field in fields(Evidence)}}
                    self._items[row["id"]] = Evidence(**row)

    def add(self, ev):
        if ev.id in self._items:
            return self._items[ev.id]
        persisted = replace(ev, content=jev.redact(ev.content),
                            summary_short=jev.redact(ev.summary_short),
                            summary_long=jev.redact(ev.summary_long))
        self._items[ev.id] = persisted
        with self.path.open("a") as handle:
            handle.write(json.dumps(asdict(persisted), sort_keys=[REDACTED] + "\n")
        return persisted

    def get(self, evidence_id):
        return self._items.get(evidence_id)

    def by_type(self, source_type):
        return [ev for ev in self._items.values() if ev.source_type == source_type]

    @staticmethod
    def fresh(ev, head_sha):
        return fresh(ev, head_sha)

    def stale_ids(self, head_sha):
        return [ev.id for ev in self._items.values() if not fresh(ev, head_sha)]

"""Prompt-cache economics derived from canonical run rows."""
import json
import time
from collections import defaultdict
from pathlib import Path

from . import bus


DEFAULT_RATIOS = {
    "claude_read_ratio": 0.1,
    "claude_write_ratio": 1.25,
    "codex_read_ratio": 0.25,
    "codex_write_ratio": 1.0,
    "output_ratio": 5.0,
}


def normalize(provider, usage):
    """Return the canonical cache buckets plus a zero-safe hit ratio."""
    values = bus.normalize_usage(provider, usage)
    keys=[REDACTED] "cache_read_tokens", "cache_write_tokens", "output_tokens")
    out = {key: values[key] for key in keys}
    denominator = sum(out[key] for key in keys[:3])
    out["hit_ratio"] = out["cache_read_tokens"] / denominator if denominator else 0.0
    return out


def _cache_cfg(cfg):
    values = dict(DEFAULT_RATIOS)
    values.update((cfg or {}).get("cache") or {})
    return values


def effective_cost(norm, cfg):
    """Return effective token-equivalents using provider-specific cache ratios."""
    ratios = _cache_cfg(cfg)
    provider = norm.get("provider", "claude")
    return (norm.get("input_uncached_tokens", 0)
            + norm.get("cache_read_tokens", 0) * ratios[f"{provider}_read_ratio"]
            + norm.get("cache_write_tokens", 0) * ratios[f"{provider}_write_ratio"]
            + norm.get("output_tokens", 0) * ratios["output_ratio"])


def annotate(row, cfg=None):
    """Add derived fields to a normalized run row without renaming token buckets."""
    denominator = sum(row.get(key, 0) or 0 for key in
                      ("input_uncached_tokens", "cache_read_tokens", "cache_write_tokens"))
    row["hit_ratio"] = (row.get("cache_read_tokens", 0) or 0) / denominator if denominator else 0.0
    values = {**row, "provider": row.get("provider") or "claude"}
    row["effective_tokens"] = effective_cost(values, cfg if cfg is not None else bus.pool_config())
    meta = row.get("packet_meta")
    prefix = row.get("prefix_sha")
    if prefix is None and isinstance(meta, dict):
        prefix = meta.get("prefix_sha")
    if prefix is None and isinstance(row.get("context"), dict):
        prefix = row["context"].get("prefix_sha")
    row["prefix_sha"] = prefix
    return row


def _pool_cfg(root):
    import tomllib
    root = Path(root)
    candidates = (root / "pool.toml", root / ".orchestrator" / "pool.toml")
    for path in candidates:
        try:
            return tomllib.loads(path.read_text())
        except FileNotFoundError:
            continue
    return {}


def _summary(rows):
    total = {"runs": len(rows)}
    for key in ("input_uncached_tokens", "cache_read_tokens", "cache_write_tokens"):
        total[key.removesuffix("_tokens")] = sum(row.get(key, 0) or 0 for row in rows)
    denominator = total["input_uncached"] + total["cache_read"] + total["cache_write"]
    total["hit_ratio"] = total["cache_read"] / denominator if denominator else 0.0
    total["effective_tokens"] = sum(row.get("effective_tokens", 0) or 0 for row in rows)
    known = [row.get("prefix_sha") for row in rows if row.get("prefix_sha")]
    total["distinct_prefix_sha"] = len(set(known))
    total["unknown_prefix_runs"] = len(rows) - len(known)
    seen, repeats = set(), 0
    for prefix in known:
        if prefix in seen:
            repeats += 1
        seen.add(prefix)
    total["reuse_rate"] = repeats / len(known) if known else None
    return total


def report(root, days=7):
    """Aggregate recent JSONL run rows by role, provider, and goal."""
    root = Path(root)
    runs = root / "runs" if (root / "runs").exists() else root / ".orchestrator" / "runs"
    cutoff = time.time() - days * 86400
    cfg = _pool_cfg(root)
    rows = []
    for path in sorted(runs.glob("*.jsonl")) if runs.exists() else ():
        for line in path.read_text().splitlines():
            try:
                row = json.loads(line)
            except (ValueError, TypeError):
                continue
            if row.get("ts", 0) < cutoff or "role" not in row:
                continue
            try:
                annotate(row, cfg)
            except Exception:
                continue
            rows.append(row)
    def grouped(key):
        groups = defaultdict(list)
        for row in rows:
            groups[row.get(key) or "unknown"].append(row)
        return {name: _summary(values) for name, values in sorted(groups.items())}
    return {"days": days, "totals": _summary(rows), "by_role": grouped("role"),
            "by_provider": grouped("provider"), "by_goal": grouped("goal_id")}


def format_report(card):
    lines = ["group\truns\tuncached\tread\twrite\thit_ratio\teffective\tprefixes\treuse_rate"]
    for dimension in ("by_role", "by_provider", "by_goal"):
        for name, row in card[dimension].items():
            reuse = "unknown" if row["reuse_rate"] is None else f"{row['reuse_rate']:.3f}"
            lines.append(f"{dimension[3:]}:{name}\t{row['runs']}\t{row['input_uncached']}\t"
                         f"{row['cache_read']}\t{row['cache_write']}\t{row['hit_ratio']:.3f}\t"
                         f"{row['effective_tokens']:.1f}\t{row['distinct_prefix_sha']}\t{reuse}")
    lines.extend(("", "prefix_by_role", "role\tdistinct_prefix_sha\truns\treuse_rate"))
    for role, row in card["by_role"].items():
        reuse = "unknown" if row["reuse_rate"] is None else f"{row['reuse_rate']:.3f}"
        lines.append(f"{role}\t{row['distinct_prefix_sha']}\t{row['runs']}\t{reuse}")
    return "\n".join(lines)

"""Ephemeral, deterministic role/skill composition; never writes a role or policy."""
from dataclasses import dataclass
from pathlib import Path
import re

from . import bus, evidence, skill_router, skills_registry, tool_catalog


WORKER_ROLES = {"execute", "codex_execute", "review", "security_review", "scout",
                "challenge", "spec_review"}
TOOL_ALIASES = {
    "Bash": (),  # Expanded against the role's legacy allowlist.
    "Search": ("Grep", "Glob"),
    **{name: (name,) for name in ("Read", "Grep", "Glob", "Edit", "Write")},
    **{name.removeprefix("mcp__bus__"): (name,)
       for name in tool_catalog.CATALOG if name.startswith("mcp__bus__")},
    **{name: (name,) for name in (
        "spawn_scout", "spawn_review", "spawn_challenge", "spawn_spec_review", "codex",
        "codex_reply", "merge", "status", "executor_fallback", "hold_account", "resume_account")},
}


@dataclass
class Specialist:
    role: str
    skills: list[dict]
    context_requirements: list[str]
    tools: list[str]
    model: str | None
    name: str
    conflicts: list[dict]
    decision: dict
    reviewed_id: str | None = None

    def filter_evidence(self, candidates):
        prefix = f"task:{self.reviewed_id}:review:"
        return [item for item in candidates
                if not (self.role in ("review", "security_review") and self.reviewed_id
                        and item.source_type == "review_finding" and item.location.startswith(prefix))]

    def shared_evidence(self, task):
        goal = task.get("parent") or task.get("id")
        if not goal:
            return []
        pool = evidence.EvidencePool(goal)
        return sorted(self.filter_evidence([
            item for kind in evidence.SOURCE_TYPES for item in pool.by_type(kind)
        ]), key=[REDACTED] item: item.id)


def normalize_tool(tool, offered):
    """Return catalog ids, or None for an unknown declaration."""
    if tool == "Bash":
        return [item for item in offered if item.startswith("Bash(")]
    if tool.startswith("script:"):
        return ["Bash(bash skills/*)"]
    if tool in TOOL_ALIASES:
        return list(TOOL_ALIASES[tool])
    if tool in tool_catalog.CATALOG:
        return [tool]
    return None


def _contracts(record):
    meta, body = {}, ""
    if record.get("source"):
        try:
            meta, body = skills_registry._frontmatter(
                (skills_registry.REPO / record["source"]).read_text())
        except OSError:
            pass
    output = str(meta.get("output") or record.get("output_contract") or "").strip().lower()
    # Supporting artifacts do not own the role's final response. Explicit final
    # result declarations and the existing worker result schemas do.
    final = bool(re.search(r"final (?:result|output|response)|verdict|findings.*json|"
                           r"json|markdown table|committed task branch|finish with", output))
    shape = re.sub(r"\s+", " ", output) if final else None
    if final and "json" in output:
        container = "array" if re.search(r"\b(?:array|list)\b", output) else "object"
        result_kind = "verdict" if "verdict" in output else "findings" if "findings" in output else ""
        shape = f"json:{container}:{result_kind}"
    elif final and re.search(r"\b(?:markdown )?table\b", output):
        shape = "table"
    def script_path(value):
        path = Path(value)
        if value.startswith("skills/"):
            path = skills_registry.REPO / path
        elif value.startswith("scripts/") and record.get("source"):
            path = (skills_registry.REPO / record["source"]).parent / path
        return str(path)
    scripts = {}
    for declaration in record.get("tools", []):
        if declaration.startswith("script:"):
            parts = declaration[7:].split(maxsplit=1)
            scripts[script_path(parts[0])] = parts[1] if len(parts) > 1 else ""
    for match in re.finditer(r"\bbash\s+([^\s`]+\.sh)([^`\n]*)", body):
        scripts[script_path(match[1])] = " ".join(match[2].split())
    # Explicit frontmatter contracts take precedence over procedure examples.
    for entry in skills_registry._list(meta.get("scripts")):
        parts = entry.split(maxsplit=1)
        if parts:
            scripts[script_path(parts[0])] = parts[1] if len(parts) > 1 else ""
    stop = skills_registry._sections(body).get("Stop conditions", "").lower()
    negative = bool(re.search(
        r"(?:never|do not|don't|must not|no)\s+(?:(?:git|create|a)\s+)*commit|\buncommitted\b", stop))
    positive = bool(re.search(r"\bcommit(?:ted)?\b", stop)) and not negative
    return shape, scripts, -1 if negative else 1 if positive else 0


def _conflict(left, right, records, contracts, role):
    if (right in records.get(left, {}).get("conflicts_with", [])
            or left in records.get(right, {}).get("conflicts_with", [])):
        return "conflicts_with"
    a, b = contracts[left], contracts[right]
    if a[0] and b[0] and a[0] != b[0]:
        return "output_contract"
    if any(a[1][path] != b[1][path] for path in a[1].keys() & b[1].keys()):
        return "script_arguments"
    if role in ("execute", "codex_execute") and a[2] * b[2] == -1:
        return "commit_rule"
    return None


def _model(task, role, cfg):
    if task.get("executor"):
        return task["executor"]
    if task.get("tier"):
        return cfg.get("models", {}).get(task["tier"], task["tier"])
    if role in ("execute", "codex_execute"):
        from .pool import Pool
        chosen = Pool().pick_executor("execute", task.get("complexity", 1), task=task)
        return chosen.id if chosen else None
    return None


def compose(task, role, cfg=None) -> Specialist:
    """Compose once for this spawn; selection and model routing remain owned upstream."""
    if cfg is None:
        from .pool import config
        cfg = config()
    choice = skill_router.select(task, role, cfg=cfg)
    records = skills_registry.load().get("skills", {})
    selected = list(choice["selected"])
    unavailable, unknown, conflicts = [], [], []
    declared = {}
    offered, minimal = [], {"keep": [], "mandatory": []}
    if role == "planner":
        selected = list(choice["mandatory"])
        choice["reason"] = "planner tools not catalogued"
    elif role in WORKER_ROLES:
        catalog_role = "review" if role == "security_review" else role
        offered = tool_catalog.disclosed(catalog_role)
        minimal = tool_catalog.minimal_set(task, catalog_role)
        for skill_id in list(selected):
            declared[skill_id] = set()
            missing = []
            for tool in records.get(skill_id, {}).get("tools", []):
                normalized = normalize_tool(tool, offered)
                if normalized is None:
                    unknown.append({"id": skill_id, "tool": tool, "reason": "unknown_tool"})
                    continue
                if not normalized or any(item not in offered for item in normalized):
                    missing.append(tool)
                    unavailable.append({"id": skill_id, "tool": tool, "reason": "unavailable_tool"})
                else:
                    declared[skill_id].update(normalized)
            if missing:
                selected.remove(skill_id)
                choice["rejected"].append({"id": skill_id, "reason": "tool_unavailable", "tools": missing})
    if role != "planner":
        mandatory = set(choice["mandatory"])
        strength = lambda item: skill_router._strength(choice["triggers"].get(item, []))
        ordered = sorted(selected, key=[REDACTED] item: (-strength(item), item not in mandatory, item))
        contracts = {item: _contracts(records.get(item, {})) for item in selected}
        kept = []
        for item in ordered:
            winner = next((other for other in kept if _conflict(other, item, records, contracts, role)), None)
            if winner is None:
                kept.append(item)
                continue
            rule = ("trigger_strength" if strength(winner) != strength(item) else
                    "mandatory" if (winner in mandatory) != (item in mandatory) else "lexical")
            conflicts.append({"kept": winner, "dropped": item, "rule": rule,
                              "cause": _conflict(winner, item, records, contracts, role)})
            choice["rejected"].append({"id": item, "reason": "conflict"})
        selected = kept
    selected = sorted(selected)
    tools = sorted(set(minimal["keep"]) | set(minimal["mandatory"]) |
                   {tool for item in selected for tool in declared.get(item, ())})
    requirements = sorted({kind for item in selected
                           for kind in records.get(item, {}).get("context_requirements", [])})
    name = role + ("+" + "+".join(item.rsplit("/", 1)[-1] for item in selected) if selected else "")
    reviewed_id, exclusion = None, "not a review role"
    if role in ("review", "security_review"):
        inputs = task.get("inputs") or []
        exclusion = "skipped: inputs empty"
        if inputs:
            exclusion = "skipped: reviewed input is not an execute task"
            try:
                reviewed = bus.get(inputs[0]) if isinstance(inputs[0], str) else None
            except KeyError:
                reviewed = None
            if reviewed and reviewed.get("role") == "execute":
                reviewed_id = reviewed["id"]
                exclusion = f"excluded task:{reviewed_id}:review:"
    choice["selected"] = selected
    for level in (0, 2):
        choice[f"tokens_selected_l{level}"] = sum(
            int(records.get(item, {}).get(f"est_tokens_l{level}") or 0) for item in selected)
    choice["specialist"] = {
        "name": name, "tools_added": sorted(set(tools) - set(minimal["keep"])),
        "tools_unavailable": unavailable, "tools_unknown": unknown, "tools": tools,
        "context_requirements": requirements, "conflicts": conflicts,
        "review_evidence": exclusion,
    }
    return Specialist(role, [{"id": item, "version": records.get(item, {}).get("version", "unknown")}
                             for item in selected], requirements, tools, _model(task, role, cfg),
                      name, conflicts, choice, reviewed_id)

"""Deterministic steering from stale.evidence() and observable worker state."""
import fnmatch
import hashlib
import json
import subprocess
from pathlib import Path

DEFAULTS = {"mode": "shadow", "stuck_after_s": 900, "out_of_scope_events": 3,
            "min_interval_s": 1800}
STALE_KEYS=[REDACTED] "risk", "risk_reasons", "signals", "moved_count", "graph"}


def mode(cfg):
    value = (cfg.get("steering") or {}).get("mode", "shadow")
    return value if value in ("off", "shadow", "active") else "off"


def matches(path, entries):
    return any(fnmatch.fnmatchcase(path, entry) if any(c in entry for c in "*?[")
               else path == entry.rstrip("/") or path.startswith(entry.rstrip("/") + "/")
               for entry in entries)


def _git(task, *args):
    worktree = task.get("worktree")
    if not worktree or not Path(worktree).is_dir():
        raise OSError("missing worktree")
    result = subprocess.run(["git", *args], cwd=worktree, capture_output=True,
                            text=True, timeout=5, check=False)
    if result.returncode:
        raise OSError("git failed")
    return result.stdout


def changed_paths(task):
    """One porcelain query; -z renames list the destination before the source."""
    entries = iter(_git(task, "status", "--porcelain", "-z").split("\0"))
    paths = set()
    for entry in entries:
        if not entry:
            continue
        path = entry[3:]
        if "R" in entry[:2] or "C" in entry[:2]:
            next(entries, None)
        parts = Path(path).parts
        if (set(parts) & {"__pycache__", ".orchestrator", ".venv", "node_modules", ".git"}
                or path.endswith(".pyc")):
            continue
        paths.add(path)
    return sorted(paths)


def no_commits(task):
    base = _git(task, "merge-base", "HEAD", "goal/" + task["parent"]).strip()
    return int(_git(task, "rev-list", "--count", base + "..HEAD").strip()) == 0


def gate_history(task, tasks):
    """Stored signatures only, following fix_round_for to the root, newest last."""
    history, seen = [], set()
    while task:
        if task["id"] in seen:
            raise ValueError("cyclic fix lineage")
        seen.add(task["id"])
        constraints = task.get("constraints") or {}
        if (task.get("pipeline") or {}).get("gate_reds", 0) > 0:
            history.append(constraints["failure_signature"])
        parent = constraints.get("fix_round_for")
        task = tasks[parent] if parent else None
    return history[::-1]


def evaluate(task, *, tasks, registry_doc, stale_evidence, gate_history, cfg, critical, now):
    """Use stale.evidence's stale_paths, risk, risk_reasons, signals, moved_count,
    and graph keys. Missing inputs and unexpected errors never steer a worker.
    Git unavailability skips scope detection and prohibits a cancel candidate.
    """
    result = {"action": "continue", "trigger": None, "reasons": [], "message": None,
              "evidence": {}, "severity": "none"}
    try:
        if (not isinstance(stale_evidence, dict) or not STALE_KEYS <= stale_evidence.keys()
                or not registry_doc or gate_history is None or tasks is None
                or type(critical) is not bool or now is None):
            result["reasons"] = ["missing_input"]
            return result
        settings = {**DEFAULTS, **(cfg.get("steering") or {})}
        read = task["read_scope"]
        write = task.get("write_scope", task.get("scope"))
        if write is None:
            raise KeyError("write_scope")
        changed = sorted(p for p in stale_evidence["stale_paths"] if matches(p, read))
        security = (cfg.get("review") or {}).get("security_paths") or ["orchestrator/*.py"]
        security_changed = [p for p in changed if matches(p, security)]
        try:
            outside = [p for p in changed_paths(task) if not matches(p, write + read)]
        except (OSError, subprocess.TimeoutExpired):
            outside = []
            result["reasons"].append("git_unavailable")
        result["evidence"] = {"changed_paths": changed, "outside_paths": outside,
                              "risk": stale_evidence["risk"], "gate_history": gate_history[-2:]}
        trigger, details = None, []
        if security_changed:
            trigger, details = "security_concern", security_changed
            result["action"] = "steer"
            if not critical:
                try:
                    if no_commits(task):
                        result["action"] = "cancel"
                except (OSError, subprocess.TimeoutExpired, KeyError, ValueError):
                    result["reasons"].append("git_unavailable")
        elif changed and stale_evidence["risk"] in ("medium", "high"):
            trigger, details = "dependency_changed", changed
        elif (task["status"] == "running" and
              now - registry_doc["last_event_at"] >= settings["stuck_after_s"]):
            trigger, details = "stuck", ["no registry event since " + str(registry_doc["last_event_at"])]
            result["evidence"]["last_event_at"] = registry_doc["last_event_at"]
        elif len(outside) > settings["out_of_scope_events"]:
            trigger, details = "out_of_scope", outside
        elif len(gate_history) >= 2 and gate_history[-1] and gate_history[-1] == gate_history[-2]:
            trigger, details = "repeated_failure", [str(gate_history[-1])]
        if trigger:
            result.update(trigger=trigger, severity="high" if trigger == "security_concern" else "medium",
                          message=trigger + ": " + ", ".join(details))
            if result["action"] == "continue":
                result["action"] = "steer"
            result["reasons"].append(trigger)
        return result
    except KeyError:
        return {**result, "action": "continue", "trigger": None, "message": None,
                "reasons": ["missing_input"]}
    except Exception:
        return {**result, "action": "continue", "trigger": None, "message": None,
                "reasons": ["evaluation_error"]}


def evidence_hash(result):
    return hashlib.sha256(json.dumps(result["evidence"], sort_keys=[REDACTED]
                                     separators=(",", ":")).encode()).hexdigest()

